# Code generated by Claude
"""
Tests of src/arm_collision.py (the collision filter for one arm's joint vectors, design plan §3.1).

    MUJOCO_GL=egl python experiments/arm_collision_test.py

1. The geom selection: only the arm under test is moving; the other arm, the torso, the three pedestal sections, the base, the battery and the neck are switched on; the scene (bench, objects, floor) is not.
2. Known poses: the home pose and the hanging rest pose of each arm do not collide (the other arm at home, the pedestal at its lowest, the neck at its drive pose).
3. Known collisions, made by IK of the hand's origin to a point inside the part: inside the torso, at the other hand, inside the neck's lower arm; and the battery (moved to the home hand's place in a copy of the model: the home pose is
   then flagged, and the unmodified model does not flag it). The margin is monotonic: a larger margin flags a superset.
4. The same answers as the full model: on 300 random poses the filter equals the contacts of the full, unfiltered model restricted to the same geoms.
5. The cost per check.
"""

import copy
import os
import sys
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import mujoco  # noqa: E402
import numpy as np  # noqa: E402

from src import robot_specs  # noqa: E402
from src.arm_collision import ArmCollisionChecker  # noqa: E402
from src.arm_kinematics import arm_chain, batch_fk, position_constraint, shoulder_origin, solve_ik  # noqa: E402
from src.grasp_rules import joint_bounds  # noqa: E402
from src.neck import set_neck_pose  # noqa: E402
from src.robot_helpers import arm_ids  # noqa: E402
from src.task_beaker_hotplate import home_targets, load_task  # noqa: E402
from src.gripper_geometry import grasp_cfg  # noqa: E402
from src.task_config import TASK_CFG  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def main():
    sim = load_task(cameras=False)
    m = sim.model
    C = grasp_cfg(m, "left")
    home = home_targets(m, TASK_CFG)
    rng = np.random.default_rng(3)
    ck = {sd: ArmCollisionChecker(m, sd, home["right" if sd == "left" else "left"]) for sd in ("left", "right")}
    body = lambda g: m.body(int(m.geom_bodyid[g])).name

    print("\n1. the geom selection")
    for sd, c in ck.items():
        moving = {body(g) for g in np.nonzero(c.moving)[0]}
        static = {body(g) for g in np.nonzero(c.active & ~c.moving)[0]}
        other = "right" if sd == "left" else "left"
        check(f"{sd}: the moving geoms are the {sd} arm's links 1 to 8, hand and fingers only", moving and all(n.startswith(f"openarm_{sd}_") and not n.endswith("link0") for n in moving), f"{len(moving)} bodies")
        check(f"{sd}: the other arm, the torso, the pedestal, the base, the battery and the neck are switched on",
              any(n.startswith(f"openarm_{other}_") for n in static) and "openarm_body_link0" in static and {"pedestal_Bottom", "pedestal_Middle", "pedestal_Top"} <= static
              and "base_link" in static and "battery" in static and any(n.startswith("neck_") for n in static), f"static bodies {sorted(static)[:4]}...")
        names_on = {body(g) for g in np.nonzero(c.active)[0]}
        check(f"{sd}: the scene (bench, hotplate, beaker, floor) is switched off", not (names_on & {"bench", "task_hotplate", "task_beaker", "world"}))

    print("\n2. known poses")
    rest = np.zeros(7)
    for sd, c in ck.items():
        check(f"{sd}: home pose does not collide", not c.check(np.array(home[sd]))[0])
        check(f"{sd}: hanging rest pose does not collide", not c.check(rest)[0])

    print("\n3. known collisions")
    chain = arm_chain(m, "left")
    sh = shoulder_origin(chain)
    lo, hi = joint_bounds(m, "left", C)
    pad = np.array(C["pad_center_in_tcp"])
    # The IK puts the hand's origin (the palm, offset (0, 0, -0.08) from the tool point) at a point inside the part: the palm cannot straddle a part, it has to overlap it. (The pad centre
    # would not do: it lies between the open fingers, which can straddle a thin part such as the torso column.)
    hand_origin = np.array([0.0, 0.0, -0.08])
    right_hand, _ = batch_fk(arm_chain(m, "right"), np.array(home["right"])[None], hand_origin)
    ckl = ck["left"]
    neck_geom = [g for g in np.nonzero(ckl.active)[0] if body(g) == "neck_lower_arm"][0]
    torso_c = ckl.data.xpos[m.body("openarm_body_link0").id]
    probes = {"inside the torso": np.array([0.0, 0.0, 0.55]), "at the right hand": right_hand[0], "inside the neck's lower arm": ckl.data.geom_xpos[neck_geom] - torso_c}
    for name, tgt in probes.items():
        Q, ok, _ = solve_ik(chain, rng.uniform(lo, hi, (200, 7)), lo, hi, position_constraint(np.tile(tgt, (200, 1)), 1e-3), hand_origin, 80)
        hit = ckl.check(Q[ok]) if ok.any() else np.zeros(0, bool)
        check(f"left hand's origin put {name} (IK, {int(ok.sum())} of 200 starts converged): every solution is flagged", ok.any() and hit.all(), f"{int(hit.sum())} flagged")
    # the battery: move it to the left hand's home place in a copy of the model
    c0 = ck["left"]
    d = c0.data
    d.qpos[c0.qadr] = home["left"]
    mujoco.mj_kinematics(c0.model, d)
    hand_world = d.xpos[m.body("openarm_left_hand").id].copy()
    m2 = copy.copy(m)
    base_pos = d.xpos[m.body("base_link").id]
    m2.body_pos[m.body("battery").id] = hand_world - base_pos
    c2 = ArmCollisionChecker(m2, "left", home["right"])
    check("battery moved into the home hand's place: the home pose is flagged", c2.check(np.array(home["left"]))[0] and not ck["left"].check(np.array(home["left"]))[0])
    Qr = rng.uniform(lo, hi, (2000, 7))
    wide = ArmCollisionChecker(m, "left", home["right"], margin=0.02)
    a, b = ck["left"].check(Qr), wide.check(Qr)
    check("a 2 cm margin flags a superset of the 0 margin", (b | ~a).all() and b.sum() >= a.sum(), f"{int(a.sum())} -> {int(b.sum())} of 2000 random poses")

    print("\n4. the same answers as the full, unfiltered model (300 random poses of the left arm)")
    full = mujoco.MjData(m)
    full.qpos[0:7] = [0.0, 0.0, 0.1527, 1.0, 0.0, 0.0, 0.0]
    for jn in robot_specs.PEDESTAL_SPECS["joints"]:
        full.qpos[m.joint(jn).qposadr[0]] = robot_specs.PEDESTAL_SPECS["lowest_command"]
    for a_, v in zip(arm_ids(m, "right")["qadr"], home["right"]):
        full.qpos[a_] = v
    for sd in ("left", "right"):
        for a_ in arm_ids(m, sd)["fingers"]:
            full.qpos[m.jnt_qposadr[m.actuator_trnid[a_, 0]]] = 0.044
    set_neck_pose(m, full, robot_specs.NECK_SPECS)
    qadr = arm_ids(m, "left")["qadr"]
    Q = rng.uniform(lo, hi, (300, 7))
    ref = np.zeros(300, bool)
    c = ck["left"]
    for n, q in enumerate(Q):
        full.qpos[qadr] = q
        mujoco.mj_kinematics(m, full)
        mujoco.mj_collision(m, full)
        g1, g2 = full.contact.geom1[:full.ncon], full.contact.geom2[:full.ncon]
        ref[n] = bool((c.active[g1] & c.active[g2] & (c.moving[g1] | c.moving[g2]) & (full.contact.dist[:full.ncon] < 0)).any())
    mine = c.check(Q)
    check("the filter gives the same collision verdict as the full model for every one of 300 random poses", (mine == ref).all(), f"{int(mine.sum())} collide in both")

    print("\n5. cost")
    t = time.time()
    c.check(Qr[:1000])
    us = 1e6 * (time.time() - t) / 1000
    check("a check takes under 1 ms", us < 1000, f"{us:.0f} us per check; {100 * ck['left'].check(Qr).mean():.1f} % of uniform random in-limit poses collide")
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
